package com.company.platform.inventory.domain;
import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
public final class Inventory {private final UUID id,tenantId,productId,warehouseLocationId;private BigDecimal onHand,reserved,committed;private Instant updatedAt;private Inventory(UUID id,UUID t,UUID p,UUID l,BigDecimal on,BigDecimal res,BigDecimal com,Instant u){if(t==null||p==null||l==null||on==null||res==null||com==null||on.signum()<0||res.signum()<0||com.signum()<0)throw new IllegalArgumentException("invalid inventory");if(on.compareTo(res.add(com))<0)throw new IllegalArgumentException("reserved stock exceeds physical stock");this.id=id==null?UUID.randomUUID():id;tenantId=t;productId=p;warehouseLocationId=l;onHand=on;reserved=res;committed=com;updatedAt=u==null?Instant.now():u;}public static Inventory create(UUID t,UUID p,UUID l){return new Inventory(null,t,p,l,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,null);}public static Inventory rehydrate(UUID id,UUID t,UUID p,UUID l,BigDecimal on,BigDecimal res,BigDecimal com,Instant u){return new Inventory(id,t,p,l,on,res,com,u);}public void adjust(BigDecimal amount){if(amount==null||onHand.add(amount).signum()<0)throw new IllegalArgumentException("invalid stock adjustment");onHand=onHand.add(amount);touch();}public void reserve(BigDecimal q){if(q==null||q.signum()<=0||available().compareTo(q)<0)throw new IllegalStateException("insufficient available stock");reserved=reserved.add(q);touch();}public void release(BigDecimal q){if(q==null||q.signum()<=0||reserved.compareTo(q)<0)throw new IllegalStateException("invalid stock release");reserved=reserved.subtract(q);touch();}public void commit(BigDecimal q){if(q==null||q.signum()<=0||reserved.compareTo(q)<0)throw new IllegalStateException("invalid allocation");reserved=reserved.subtract(q);committed=committed.add(q);touch();}private void touch(){updatedAt=Instant.now();}public BigDecimal available(){return onHand.subtract(reserved).subtract(committed);}public UUID id(){return id;}public UUID tenantId(){return tenantId;}public UUID productId(){return productId;}public UUID warehouseLocationId(){return warehouseLocationId;}public BigDecimal onHand(){return onHand;}public BigDecimal reserved(){return reserved;}public BigDecimal committed(){return committed;}public Instant updatedAt(){return updatedAt;}}
